def es_primo(n):
    if n < 2:
        return False
    d = 2
    while d * d <= n:
        if n % d == 0:
            return False
        d = d + 1
    return True

n = int(input())
if es_primo(n):
    print(f"{n} es primo")
else:
    print(f"{n} no es primo")
